∀
  {n : Nat} {Ω : Type u} (B : Finset.{0} (Fin n)) (g : Ω → Real) (r : Ω → Ω → Real),
  have m : Nat := @Finset.card.{0} (Fin n) B;
  have H : Ω → Ω → Real := fun (o y : Ω) =>
    @HAdd.hAdd.{0, 0, 0} Real Real Real (@instHAdd.{0} Real Real.instAdd)
      (@HAdd.hAdd.{0, 0, 0} Real Real Real (@instHAdd.{0} Real Real.instAdd) (g o) (g y))
      (@HMul.hMul.{0, 0, 0} Real Real Real (@instHMul.{0} Real Real.instMul)
        (@Shao.OQ5.P41.FiniteBackgroundPerturbation.backgroundScale n B) (r o y));
  have sampleH : (Fin m → Ω) → Fin m → Fin m → Real := fun (ζ : Fin m → Ω) (i j : Fin m) => H (ζ i) (ζ j);
  have U : (Fin m → Ω) → Real := fun (ζ : Fin m → Ω) => @Shao.OQ6.FiniteRows.uStatistic m (sampleH ζ);
  have RH : (Fin m → Ω) → Real := fun (ζ : Fin m → Ω) => Real.sqrt (@Shao.OQ6.FiniteRows.jackknifeSq m (sampleH ζ));
  have Tuncenter : (Fin m → Ω) → Real := fun (ζ : Fin m → Ω) =>
    @ite.{1} Real (@Eq.{1} Real (RH ζ) (@OfNat.ofNat.{0} Real (nat_lit 0) (@Zero.toOfNat0.{0} Real Real.instZero)))
      (Real.decidableEq (RH ζ) (@OfNat.ofNat.{0} Real (nat_lit 0) (@Zero.toOfNat0.{0} Real Real.instZero)))
      (@OfNat.ofNat.{0} Real (nat_lit 0) (@Zero.toOfNat0.{0} Real Real.instZero))
      (@HDiv.hDiv.{0, 0, 0} Real Real Real (@instHDiv.{0} Real (@DivInvMonoid.toDiv.{0} Real Real.instDivInvMonoid))
        (@HMul.hMul.{0, 0, 0} Real Real Real (@instHMul.{0} Real Real.instMul)
          (Real.sqrt (@Nat.cast.{0} Real Real.instNatCast m)) (U ζ))
        (RH ζ));
  ∀ (ζ : Fin m → Ω),
    @Eq.{1} Real
      (@Shao.OQ5.P41.FiniteBackgroundPhysicalTransport.physicalStatistic.{u} m Ω g
        (@Shao.OQ5.P41.FiniteBackgroundPhysicalTransport.scaledResidual.{u} n Ω B r) ζ)
      (Tuncenter ζ)
